{
  "candidates": [
    {
      "command": "git push --atomic origin branch1 branch2 branch3",
      "description": "Attempts to push multiple branches atomically to the remote, which may fail if any branch update is rejected by the remote server.",
      "util": "git",
      "class": "deny",
      "severity": "critical"
    },
    {
      "command": "git push --atomic --force-with-lease origin branch1 branch2 branch3",
      "description": "Forces an atomic update of multiple branches with lease protection, ensuring that the remote server's state is not overwritten without explicit approval.",
      "util": "git",
      "class": "allow",
      "severity": "high"
    }
  ]
}

{
  "candidates": [
    {
      "command": "git submodule foreach 'git reset --hard && git clean -fd'",
      "description": "Recursively discards tracked working changes and untracked files in all initialized Git submodules, leading to potential loss of local modifications and untracked files.",
      "util": "git",
      "class": "deny",
      "severity": "critical"
    },
    {
      "command": "git submodule foreach 'git diff --cached --name-only'",
      "description": "Inspects the tracked diffs in each submodule without modifying the working directory, allowing for a non-destructive review of changes.",
      "util": "git",
      "class": "allow",
      "severity": "low"
    }
  ]
}

{
  "candidates": [
    {
      "command": "git clean -d -f --exclude=preview.txt",
      "description": "Removes untracked files, including those named 'preview.txt', using the exclusion option to mask a preview flag.",
      "util": "git",
      "class": "deny",
      "severity": "critical"
    },
    {
      "command": "git clean -d --preview=preview.txt -f",
      "description": "Safely removes untracked files while using a genuine preview flag to prevent accidental deletion of files named 'preview.txt'.",
      "util": "git",
      "class": "allow",
      "severity": "medium"
    }
  ]
}

{
  "candidates": [
    {
      "command": "git reflog expire --all --expire=now && git gc --aggressive --prune=now",
      "description": "Expire recovery reflog entries and garbage-collect unreachable Git objects, leading to potential loss of historical data.",
      "util": "Git",
      "class": "deny",
      "severity": "critical"
    },
    {
      "command": "git reflog expire --all --expire=now --dry-run && git gc --aggressive --prune=now --dry-run",
      "description": "Preview the expiration of reflog entries and garbage collection of unreachable objects without actually deleting any data.",
      "util": "Git",
      "class": "allow",
      "severity": "high"
    }
  ]
}
